package com.idr.navigator.engine; public class NavigationFusion { public record Fix(long time,double lat,double lon,double alt,double accuracy,double speed,double speedError,double bearing,double bearingError) { public boolean speedValid(){return Double.isFinite(speed)&&speed>=0&&speed<=80&&Double.isFinite(speedError)&&speedError>=0&&speedError<=1;} public boolean courseValid(){return speedValid()&&speed>3&&Double.isFinite(bearing)&&Double.isFinite(bearingError)&&bearingError>=0&&bearingError<=20;} } }